<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;800&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#D40920;
    --blue:#144E8C;
    --yellow:#F9C606;
    --black:#0A0A0A;
    --white:#F5F3EE;
    --grey:#B9B5AC;
    --line:12px;
  }
  *{margin:0;padding:0;box-sizing:border-box;}
  html{scroll-behavior:smooth;}
  body{
    font-family:'Archivo',Helvetica,Arial,sans-serif;
    background:var(--white);
    color:var(--black);
    line-height:1.55;
  }

  /* ---------- Header ---------- */
  header{
    border-bottom:var(--line) solid var(--black);
    display:flex;
    flex-wrap:wrap;
  }
  header .masthead{
    flex:1 1 340px;
    padding:2.5rem 2rem 2rem;
    border-right:var(--line) solid var(--black);
  }
  header .kicker{
    font-size:.8rem;
    letter-spacing:.28em;
    text-transform:uppercase;
    font-weight:600;
    color:#555;
  }
  header h1{
    font-size:clamp(2.1rem,6vw,4rem);
    font-weight:800;
    text-transform:uppercase;
    letter-spacing:-.01em;
    line-height:1.02;
    margin:.6rem 0 .8rem;
  }
  header .byline{
    font-size:1.05rem;
    font-weight:600;
  }
  header .byline span{color:#555;font-weight:400;}
  header .blocks{
    flex:0 0 220px;
    display:flex;
    flex-direction:column;
    min-height:150px;
  }
  header .blocks .r{flex:3;background:var(--red);}
  header .blocks .w{flex:1;background:var(--white);border-top:var(--line) solid var(--black);}
  header .blocks .row{flex:1;display:flex;border-top:var(--line) solid var(--black);}
  header .blocks .row .b{flex:1;background:var(--blue);}
  header .blocks .row .y{flex:1;background:var(--yellow);border-left:var(--line) solid var(--black);}

  /* ---------- Hero ---------- */
  .hero{
    display:flex;
    flex-wrap:wrap;
    border-bottom:var(--line) solid var(--black);
  }
  .hero .canvas{
    flex:1 1 420px;
    padding:3rem 2rem;
    display:flex;
    align-items:center;
    justify-content:center;
    border-right:var(--line) solid var(--black);
  }
  /* The picture, after the fact sheet's description */
  .painting{
    width:min(420px,80vw);
    aspect-ratio:1/1;
    background:var(--white);
    border:var(--line) solid var(--black);
    display:grid;
    grid-template-columns:55% 45%;
    grid-template-rows:58% 42%;
  }
  .painting .red{
    background:var(--red);
    grid-column:2;grid-row:1;
    border-left:var(--line) solid var(--black);
    border-bottom:var(--line) solid var(--black);
  }
  .painting .white-top-left{background:var(--white);grid-column:1;grid-row:1;}
  .painting .blue{
    background:var(--blue);
    grid-column:1;grid-row:2;
    border-right:var(--line) solid var(--black);
    border-top:var(--line) solid var(--black);
  }
  .painting .yellow{
    background:var(--yellow);
    grid-column:2;grid-row:2;
    border-top:var(--line) solid var(--black);
  }
  .hero .intro{
    flex:1 1 340px;
    padding:3rem 2rem;
    display:flex;
    flex-direction:column;
    justify-content:center;
    gap:1.2rem;
  }
  .hero .intro .lede{
    font-size:clamp(1.15rem,2.4vw,1.5rem);
    font-weight:600;
    line-height:1.4;
  }
  .hero .intro p{color:#333;max-width:34em;}

